"use client";

import { Bar, BarChart, ResponsiveContainer, XAxis, YAxis, Tooltip } from "recharts";

const data = [
    { name: "Mon", visitors: 400 },
    { name: "Tue", visitors: 300 },
    { name: "Wed", visitors: 550 },
    { name: "Thu", visitors: 450 },
    { name: "Fri", visitors: 600 },
    { name: "Sat", visitors: 200 },
    { name: "Sun", visitors: 150 },
];

export default function AnalyticsPage() {
    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-2xl font-bold tracking-tight text-gray-900">Analytics</h1>
                <p className="text-sm text-gray-500">Traffic and engagement reports.</p>
            </div>

            <div className="rounded-xl border bg-white p-6 shadow-sm">
                <h3 className="mb-6 text-lg font-semibold text-gray-900">Weekly Visitors</h3>
                <div className="h-[300px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={data}>
                            <XAxis
                                dataKey="name"
                                stroke="#888888"
                                fontSize={12}
                                tickLine={false}
                                axisLine={false}
                            />
                            <YAxis
                                stroke="#888888"
                                fontSize={12}
                                tickLine={false}
                                axisLine={false}
                                tickFormatter={(value) => `${value}`}
                            />
                            <Tooltip
                                cursor={{ fill: '#f3f4f6' }}
                                contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                            />
                            <Bar
                                dataKey="visitors"
                                fill="#2563eb"
                                radius={[4, 4, 0, 0]}
                            />
                        </BarChart>
                    </ResponsiveContainer>
                </div>
            </div>

            <div className="grid gap-6 md:grid-cols-2">
                <div className="rounded-xl border bg-white p-6">
                    <h3 className="mb-4 font-semibold text-gray-900">Top Sources</h3>
                    <div className="space-y-3">
                        <SourceBar label="Google" percent={45} />
                        <SourceBar label="Direct" percent={30} />
                        <SourceBar label="Instagram" percent={15} />
                        <SourceBar label="Other" percent={10} />
                    </div>
                </div>
                <div className="rounded-xl border bg-white p-6">
                    <h3 className="mb-4 font-semibold text-gray-900">Top Pages</h3>
                    <ul className="space-y-3 text-sm">
                        <li className="flex justify-between border-b pb-2">
                            <span>/home</span>
                            <span className="font-medium">1,234 views</span>
                        </li>
                        <li className="flex justify-between border-b pb-2">
                            <span>/work/university-max</span>
                            <span className="font-medium">856 views</span>
                        </li>
                        <li className="flex justify-between border-b pb-2">
                            <span>/contact</span>
                            <span className="font-medium">432 views</span>
                        </li>
                    </ul>
                </div>
            </div>
        </div>
    );
}

function SourceBar({ label, percent }: { label: string, percent: number }) {
    return (
        <div className="space-y-1">
            <div className="flex justify-between text-xs text-gray-600">
                <span>{label}</span>
                <span>{percent}%</span>
            </div>
            <div className="h-2 w-full overflow-hidden rounded-full bg-gray-100">
                <div
                    className="h-full bg-blue-500"
                    style={{ width: `${percent}%` }}
                />
            </div>
        </div>
    );
}
